/** Return the charge in dollars for a stay of whole, nonnegative minutes. */
export function parkingFee(minutes) {
  return Math.min(12, 2 * Math.ceil(minutes / 30));
}

reference:
/** Return the charge in dollars for a stay of whole, nonnegative minutes. */
export function parkingFee(minutes) {
  return Math.min(12, 2 * Math.ceil(Math.max(0, minutes - 15) / 30));
}

