function minuteOfDay(time) {
  const [hours, minutes] = time.split(':').map(Number);
  return hours * 60 + minutes;
}

export function shiftMinutes(start, end) {
  const elapsed = minuteOfDay(end) - minuteOfDay(start);
  return elapsed < 0 ? elapsed + 1440 : elapsed;
}

reference:
function minuteOfDay(time) {
  const [hours, minutes] = time.split(':').map(Number);
  return hours * 60 + minutes;
}

export function shiftMinutes(start, end) {
  const elapsed = minuteOfDay(end) - minuteOfDay(start);
  const duration = elapsed < 0 ? elapsed + 1440 : elapsed;
  return Math.round(duration / 5) * 5;
}
